#include <stdio.h>
#include <stdlib.h>
int main() {
    int n, k; char dir;
    if (scanf("%d %d %c", &n, &k, &dir) != 3) return 0;
    int *a = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    k %= n;
    int shift = (dir == 'R' || dir == 'r') ? (n - k) % n : k;
    for (int i = 0; i < n; i++) {
        if (i > 0) putchar(' ');
        printf("%d", a[(shift + i) % n]);
    }
    putchar('\n');
    free(a);
    return 0;
}

