const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (toks.length > 0) {
        const n = parseInt(toks[0], 10);
        const k = parseInt(toks[1], 10) % n;
        const dir = toks[2].toUpperCase();
        const arr = toks.slice(3, 3 + n);
        const rot = (dir === "R") ? (k > 0 ? arr.slice(-k).concat(arr.slice(0, -k)) : arr) : (k > 0 ? arr.slice(k).concat(arr.slice(0, k)) : arr);
        console.log(rot.join(" "));
    }
}
main();

